import{_ as r,o as a,c as e,ae as n}from"./chunks/framework.CFyvOAXl.js";const u=JSON.parse('{"title":"AI Infra 招聘岗位全景","description":"","frontmatter":{},"headers":[],"relativePath":"program/interview/aiinfra_jobs.md","filePath":"program/interview/aiinfra_jobs.md","lastUpdated":1786894185000}'),i={name:"program/interview/aiinfra_jobs.md"};function o(d,t,l,s,h,g){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-infra-招聘岗位全景" tabindex="-1">AI Infra 招聘岗位全景 <a class="header-anchor" href="#ai-infra-招聘岗位全景" aria-label="Permalink to &quot;AI Infra 招聘岗位全景&quot;">​</a></h1><blockquote><p>首次编写：2026-08-12 | 最后更新：2026-08-12</p></blockquote><blockquote><p><strong>AI Infra / KV Cache 面试系列</strong></p><ul><li><a href="./aiinfra_overview.html">导读</a></li><li><strong>招聘岗位全景</strong> ← 当前文章</li><li><a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a></li><li><a href="./aiinfra_interview_questions.html">面经与高频考点</a></li><li><a href="./aiinfra_system_design.html">系统设计专题</a></li><li><a href="./aiinfra_2month_plan.html">2 个月面试复习计划</a></li><li><a href="./aiinfra_resources.html">资源汇总</a></li></ul></blockquote><hr><h2 id="⚠️-信息来源说明-务必先读" tabindex="-1">⚠️ 信息来源说明（务必先读） <a class="header-anchor" href="#⚠️-信息来源说明-务必先读" aria-label="Permalink to &quot;⚠️ 信息来源说明（务必先读）&quot;">​</a></h2><p>本页是<strong>结构化盘点</strong>，基于该领域公开、稳定的招聘格局整理。WebSearch/WebFetch 工具被沙箱阻断，但 <strong>Bash curl 实测</strong>：arxiv/github/nowcoder/vllm/sglang 等可达，google/huggingface/Boss 直聘不可达（后者需登录+JS）。</p><ul><li>✅ <strong>已核实</strong>：<a href="./aiinfra_resources.html">资源汇总</a> 的 arXiv 论文链接、<a href="./aiinfra_interview_questions.html">题库 7.0 节</a> 的牛客真实面经帖。</li><li>❓ <strong>仍需 [实时核对]</strong>：本页的具体团队、薪资区间、最新 HC--请用以下渠道核对：</li></ul><p>薪资区间、具体团队、最新岗位请用以下实时渠道核对（<a href="./aiinfra_resources.html">资源汇总</a> 有清单）：</p><ul><li><strong>国内</strong>：Boss 直聘、牛客网（面经+内推）、脉脉（薪资+团队风评）、公司招聘官网、知乎/小红书面经帖。</li><li><strong>海外</strong>：LinkedIn、levels.fyi、一亩三分地、各家 careers 页。</li></ul><blockquote><p>文中凡标 <strong>[实时核对]</strong> 的字段，请以最新招聘信息为准。</p></blockquote><hr><h2 id="_1-岗位类型划分" tabindex="-1">1. 岗位类型划分 <a class="header-anchor" href="#_1-岗位类型划分" aria-label="Permalink to &quot;1. 岗位类型划分&quot;">​</a></h2><p>AI Infra 是个统称，不同公司组织拆法不同。按&quot;离模型/离硬件&quot;的光谱，可分五类。<strong>KV Cache 方向主要集中在第 1、3 类，其次第 5 类。</strong></p><h3 id="_1-1-推理系统-serving-kv-cache-主战场-⭐⭐⭐⭐⭐" tabindex="-1">1.1 推理系统 / Serving（KV Cache 主战场）⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_1-1-推理系统-serving-kv-cache-主战场-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;1.1 推理系统 / Serving（KV Cache 主战场）⭐⭐⭐⭐⭐&quot;">​</a></h3><ul><li><strong>做什么</strong>：LLM 推理引擎设计与实现--调度器、批处理、KV Cache 管理、显存规划、分离式架构、多租户。</li><li><strong>技能栈</strong>：C++/Python、CUDA 基础、熟悉 vLLM/SGLang/TensorRT-LLM/TGI/LMDeploy 至少其一的源码、理解 PagedAttention/连续批处理/PD 分离、分布式（TP/PP/EP）。</li><li><strong>KV Cache 关联</strong>：直接负责。本 Wiki 的技术主线就是为这个岗准备的。</li><li><strong>典型团队</strong>：字节火山方舟/豆包、阿里 PAI/通义、腾讯机智/混元、华为诺亚/昇腾、百度文心、DeepSeek、Moonshot、智谱、MiniMax、商汤、阶跃星辰、美团/小红书大模型平台组、海外 NVIDIA TensorRT-LLM、Meta (vLLM/PyTorch)、Microsoft (DeepSpeed/vLLM)、Google (Pathways/JAX)、Together/Anyscale 等。</li></ul><h3 id="_1-2-训练框架-分布式-⭐⭐⭐⭐" tabindex="-1">1.2 训练框架 / 分布式 ⭐⭐⭐⭐ <a class="header-anchor" href="#_1-2-训练框架-分布式-⭐⭐⭐⭐" aria-label="Permalink to &quot;1.2 训练框架 / 分布式 ⭐⭐⭐⭐&quot;">​</a></h3><ul><li><strong>做什么</strong>：大模型预训练/微调框架--Megatron/DeepSpeed 类 3D 并行、通信优化、checkpoint、容错。</li><li><strong>技能栈</strong>：NCCL/分布式通信、PyTorch 内部、TP/PP/DP/EP/CP/SP、ZeRO、流水线气泡优化、显存复用。</li><li><strong>KV Cache 关联</strong>：弱（训练无 KV Cache）。但 attention/通信/并行的底层知识高度复用，常与推理岗互转。</li><li><strong>典型团队</strong>：同上大厂训练团队，尤其头部大模型公司的 pretrain infra。</li></ul><h3 id="_1-3-算子-kernel-⭐⭐⭐⭐⭐" tabindex="-1">1.3 算子 / Kernel ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_1-3-算子-kernel-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;1.3 算子 / Kernel ⭐⭐⭐⭐⭐&quot;">​</a></h3><ul><li><strong>做什么</strong>：高性能算子开发--FlashAttention 类融合 attention、量化算子、MoE 路由/组合算子、自定义 CUDA/Triton kernel。</li><li><strong>技能栈</strong>：CUDA（warp/shared memory/occupancy/async copy/TMA）、CUTLASS、Triton、GPU 微架构（Hopper/Blackwell）、性能 profiling（Nsight）。</li><li><strong>KV Cache 关联</strong>：强。PagedAttention kernel、MLA kernel、FP8 KV 量化算子都属此类。</li><li><strong>典型团队</strong>：NVIDIA（cuBLAS/cutlass/TRT-LLM）、Meta、各芯片厂、大厂 kernel 组、DeepSeek/Moonshot/智谱的 infra-kernel 组。</li></ul><h3 id="_1-4-硬件-编译-⭐⭐⭐" tabindex="-1">1.4 硬件 / 编译 ⭐⭐⭐ <a class="header-anchor" href="#_1-4-硬件-编译-⭐⭐⭐" aria-label="Permalink to &quot;1.4 硬件 / 编译 ⭐⭐⭐&quot;">​</a></h3><ul><li><strong>做什么</strong>：图编译（TensorRT/XLA/TorchInductor/MLIR）、算子库、芯片侧算子适配、硬件协同设计。</li><li><strong>技能栈</strong>：编译器后端、MLIR、硬件架构、CUTLASS、芯片 ISA。</li><li><strong>KV Cache 关联</strong>：中。编译器要支持 paged/MLA 等 memory 访问 pattern。</li><li><strong>典型团队</strong>：NVIDIA、AMD、Intel、华为昇腾、寒武纪、燧原、壁仞、摩尔线程、各家 AI 编译组。</li></ul><h3 id="_1-5-平台-工程化-⭐⭐⭐" tabindex="-1">1.5 平台 / 工程化 ⭐⭐⭐ <a class="header-anchor" href="#_1-5-平台-工程化-⭐⭐⭐" aria-label="Permalink to &quot;1.5 平台 / 工程化 ⭐⭐⭐&quot;">​</a></h3><ul><li><strong>做什么</strong>：大规模训练/推理集群调度、容错、监控、多租户、成本优化、CI/CD。</li><li><strong>技能栈</strong>：K8s/调度系统、分布式系统、SRE、Go/Java、监控体系。</li><li><strong>KV Cache 关联</strong>：中。分离式推理的 KV 池化、多租户 KV 隔离、全局调度属此范畴（Mooncake 类）。</li><li><strong>典型团队</strong>：大厂云平台/AI 平台组。</li></ul><hr><h2 id="_2-公司盘点-国内为主" tabindex="-1">2. 公司盘点（国内为主） <a class="header-anchor" href="#_2-公司盘点-国内为主" aria-label="Permalink to &quot;2. 公司盘点（国内为主）&quot;">​</a></h2><blockquote><p>仅列出有 AI Infra 招聘需求的代表性公司/团队，<strong>非完整列表</strong>，排序无意义。薪资、HC 以 [实时核对] 为准。</p></blockquote><h3 id="_2-1-大厂-云" tabindex="-1">2.1 大厂 / 云 <a class="header-anchor" href="#_2-1-大厂-云" aria-label="Permalink to &quot;2.1 大厂 / 云&quot;">​</a></h3><table tabindex="0"><thead><tr><th>公司</th><th>代表团队/产品</th><th>方向侧重</th><th>备注</th></tr></thead><tbody><tr><td>字节跳动</td><td>火山方舟、豆包大模型、AML</td><td>推理 serving、训练、kernel 全栈</td><td>国内 AI Infra HC 最多的公司之一，SGLang/vLLM 都有深度参与</td></tr><tr><td>阿里云</td><td>PAI、通义、弹性计算</td><td>推理、训练、平台</td><td>有自研推理框架与硬件协同</td></tr><tr><td>腾讯</td><td>机智、混元、腾讯云</td><td>训练框架、推理、平台</td><td>机智是大规模训练平台代表</td></tr><tr><td>华为</td><td>诺亚方舟、昇腾、MindSpore</td><td>全栈含硬件/编译</td><td>软硬协同，昇腾生态</td></tr><tr><td>百度</td><td>文心、飞桨</td><td>训练框架、推理</td><td>飞桨 + 文心</td></tr><tr><td>美团/小红书/快手</td><td>大模型平台组</td><td>推理 serving 为主</td><td>应用驱动，工程导向</td></tr></tbody></table><blockquote><p>📌 <strong>实时招聘信号（2026-08-12 抓取自牛客，✅ 已核实）</strong>：<a href="https://www.nowcoder.com/discuss/353158230501171200" target="_blank" rel="noreferrer">百度基础架构部急招 异构计算/CUDA 研发/C++/HPC 优化</a>--提前批、部门直面。印证大厂基础架构部对 CUDA/HPC 算子人才的需求。快手/美团/华为海思的 AI Infra 校招面经见 <a href="./aiinfra_interview_questions.html">题库 §7.0</a>。</p></blockquote><h3 id="_2-2-大模型创业公司-明星团队-kv-cache-方向高密度" tabindex="-1">2.2 大模型创业公司（明星团队，KV Cache 方向高密度） <a class="header-anchor" href="#_2-2-大模型创业公司-明星团队-kv-cache-方向高密度" aria-label="Permalink to &quot;2.2 大模型创业公司（明星团队，KV Cache 方向高密度）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>公司</th><th>团队亮点</th><th>与 KV Cache 关系</th></tr></thead><tbody><tr><td>DeepSeek（深度求索）</td><td>MLA、PD 分离、MoE 训推一体</td><td><strong>MLA 的提出者</strong>，KV Cache 方向面试必考其架构</td></tr><tr><td>Moonshot（月之暗面）</td><td>长上下文、Mooncake KVCache-centric 分离式架构</td><td><strong>KV Cache 池化的代表</strong>，面试高频</td></tr><tr><td>智谱（Zhipu/GLM）</td><td>GLM 系列、SGLang 协同</td><td>作者本博客就在做 SGLang×GLM-5.2 KV Cache</td></tr><tr><td>MiniMax</td><td>大规模推理、线性/稀疏 attention 探索</td><td>推理优化有特色</td></tr><tr><td>阶跃星辰（StepFun）</td><td>多模态、大模型训练</td><td>infra 团队扩张中</td></tr><tr><td>百川/零一/面壁 等</td><td>各有侧重</td><td>训推 infra</td></tr></tbody></table><h3 id="_2-3-芯片厂" tabindex="-1">2.3 芯片厂 <a class="header-anchor" href="#_2-3-芯片厂" aria-label="Permalink to &quot;2.3 芯片厂&quot;">​</a></h3><p>NVIDIA（TRT-LLM、cutlass、cuBLAS）、AMD（ROCm/MIOpen）、Intel（oneAPI/SYCL）、华为昇腾、寒武纪、燧原、壁仞、摩尔线程、海光等。<strong>硬件厂 KV Cache 工作偏 kernel/编译侧</strong>。</p><h3 id="_2-4-海外-供参考" tabindex="-1">2.4 海外（供参考） <a class="header-anchor" href="#_2-4-海外-供参考" aria-label="Permalink to &quot;2.4 海外（供参考）&quot;">​</a></h3><ul><li><strong>NVIDIA</strong>：TensorRT-LLM、cutlass、vLLM 社区核心。</li><li><strong>Meta</strong>：vLLM、PyTorch、xformers、Megatron 的发源地，开源贡献巨大。</li><li><strong>Microsoft</strong>：DeepSpeed、vLLM 协同、Azure 推理。</li><li><strong>Google</strong>：Pathways、JAX、TPU 软硬一体。</li><li><strong>OpenAI / Anthropic</strong>：自研推理栈，HC 少而精。</li><li><strong>Together / Anyscale / Replicate / Fireworks</strong>：纯推理服务公司，技术驱动。</li></ul><hr><h2 id="_3-典型-jd-拆解-推理系统岗为例" tabindex="-1">3. 典型 JD 拆解（推理系统岗为例） <a class="header-anchor" href="#_3-典型-jd-拆解-推理系统岗为例" aria-label="Permalink to &quot;3. 典型 JD 拆解（推理系统岗为例）&quot;">​</a></h2><p>下面是一个<strong>合成版</strong>典型 JD（综合多家推理系统岗的共性要求），用于反推复习重点。<strong>非任何一家公司的原文 JD</strong>，[实时核对] 真实 JD。</p><blockquote><p><strong>岗位：大模型推理系统工程师 / Infra Engineer - LLM Serving</strong></p><p>职责：</p><ul><li>设计与实现大规模 LLM 推理引擎，优化吞吐与延迟（TTFT/TPOT/Goodput）。</li><li>负责 KV Cache 管理、批处理调度、显存规划、分离式推理架构。</li><li>参与高性能算子（attention/量化）的开发与调优。</li><li>支持多模态、长上下文、MoE 模型的推理优化。</li><li>线上集群的稳定性、成本与多租户隔离。</li></ul><p>要求：</p><ul><li>熟悉 C++/Python，扎实的系统编程与数据结构功底。</li><li>深入理解 Transformer、attention、KV Cache、GQA/MQA/MLA。</li><li>熟悉 vLLM/SGLang/TensorRT-LLM 至少其一的设计与源码。</li><li>熟悉 GPU 架构与 CUDA 编程，有算子优化经验加分。</li><li>熟悉分布式训练/推理（TP/PP/EP/CP）、NCCL 通信。</li><li>有大规模线上系统经验、熟悉容器/调度加分。</li><li>有顶会论文（OSDI/SOSP/MLSys/ASPLOS/ISCA/SC）或开源贡献加分。</li></ul></blockquote><p><strong>反推复习重点（映射到本 Wiki）：</strong></p><table tabindex="0"><thead><tr><th>JD 关键词</th><th>复习位置</th></tr></thead><tbody><tr><td>KV Cache 管理</td><td><a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a> 全文</td></tr><tr><td>批处理调度</td><td>同上 §3.2/§3.3 连续批处理</td></tr><tr><td>显存规划</td><td>同上 §2 显存建模</td></tr><tr><td>分离式推理</td><td>同上 §6.4</td></tr><tr><td>GQA/MQA/MLA</td><td>同上 §4.1/§4.2</td></tr><tr><td>推理引擎源码</td><td><a href="./aiinfra_resources.html">资源汇总</a> + <a href="./aiinfra_2month_plan.html">2 个月计划</a> 第 3-4 周</td></tr><tr><td>GPU/CUDA/算子</td><td>计划第 1、7 周 + 资源汇总</td></tr><tr><td>分布式/通信</td><td>计划第 7 周</td></tr><tr><td>系统设计</td><td><a href="./aiinfra_interview_questions.html">面经</a> 系统设计章 + <a href="./aiinfra_system_design.html">系统设计专题</a></td></tr></tbody></table><h3 id="_3-1-技能自评矩阵" tabindex="-1">3.1 技能自评矩阵 <a class="header-anchor" href="#_3-1-技能自评矩阵" aria-label="Permalink to &quot;3.1 技能自评矩阵&quot;">​</a></h3><p>用下表量化自己的准备度，<strong>短板项优先排进 <a href="./aiinfra_2month_plan.html">2 个月计划</a></strong>。每项自评 4 档：①没听过 ②能讲概念 ③能讲清原理/推导 ④能改源码/手撕/优化。</p><table tabindex="0"><thead><tr><th>技能</th><th>自评①-④</th><th>复习位置</th><th>目标档</th></tr></thead><tbody><tr><td>KV Cache 显存建模与口算</td><td>☐</td><td><a href="./aiinfra_kvcache_deep_dive.html">KV Cache §2</a></td><td>④</td></tr><tr><td>PagedAttention 原理与源码</td><td>☐</td><td>同 §3.2 + vLLM 源码</td><td>④</td></tr><tr><td>连续批处理 / 调度</td><td>☐</td><td>同 §3.3 + vLLM/SGLang 源码</td><td>④</td></tr><tr><td>GQA/MQA/MLA（含推导）</td><td>☐</td><td>同 §4.1/§4.2/§4.2.1</td><td>④</td></tr><tr><td>KV 量化（FP8/per-channel）</td><td>☐</td><td>同 §4.3</td><td>③</td></tr><tr><td>RadixAttention / 前缀复用</td><td>☐</td><td>同 §5 + SGLang 源码</td><td>④</td></tr><tr><td>长上下文（sink/streaming/window）</td><td>☐</td><td>同 §6.2</td><td>③</td></tr><tr><td>分离式推理 / KV 池化（Mooncake 等）</td><td>☐</td><td>同 §6.4</td><td>④</td></tr><tr><td>FlashAttention 原理</td><td>☐</td><td><a href="./aiinfra_interview_questions.html">面经 Q3.1-3.2</a></td><td>③</td></tr><tr><td>CUDA/Triton 算子</td><td>☐</td><td><a href="./aiinfra_2month_plan.html">计划第 2、7 周</a></td><td>③</td></tr><tr><td>分布式（TP/PP/EP/CP/NCCL）</td><td>☐</td><td><a href="./aiinfra_interview_questions.html">面经第 4 章</a></td><td>③</td></tr><tr><td>系统设计（LLM serving）</td><td>☐</td><td><a href="./aiinfra_system_design.html">系统设计专题</a></td><td>④</td></tr><tr><td>手撕 attention/LRU/调度</td><td>☐</td><td><a href="./aiinfra_interview_questions.html">面经附录 A</a></td><td>④</td></tr></tbody></table><blockquote><p>经验法则：目标岗位是<strong>推理系统/serving</strong> -&gt; 表中前 8 项必须到 ④；<strong>算子/kernel</strong> 岗 -&gt; FlashAttention/CUDA/手撕到 ④；<strong>大厂训练框架</strong>岗 -&gt; 分布式到 ④、KV 项到 ③。</p></blockquote><hr><h2 id="_4-职级与薪资-结构化参考-实时核对" tabindex="-1">4. 职级与薪资（结构化参考，[实时核对]） <a class="header-anchor" href="#_4-职级与薪资-结构化参考-实时核对" aria-label="Permalink to &quot;4. 职级与薪资（结构化参考，[实时核对]）&quot;">​</a></h2><blockquote><p>薪资受年份、职级、股票、城市、个人背景影响极大，下表仅为<strong>量级感知</strong>，绝非报价。务必用 levels.fyi / 脉脉 / 牛客核对最新。</p></blockquote><table tabindex="0"><thead><tr><th>档位</th><th>典型对应</th><th>大致年包（国内，人民币，量级）</th><th>大致年包（海外，美元，量级）</th></tr></thead><tbody><tr><td>应届/初级</td><td>校招 SP/SSP、社招 1-3 年</td><td>40w - 80w</td><td>150k - 250k 美元</td></tr><tr><td>中级</td><td>社招 3-6 年、大厂 P6/T5 左右</td><td>80w - 150w</td><td>250k - 450k 美元</td></tr><tr><td>高级/资深</td><td>P7/T6+、技术骨干</td><td>150w - 300w+</td><td>400k - 700k+ 美元</td></tr><tr><td>专家/架构</td><td>P8/T7+、团队负责人</td><td>300w+ 上不封顶</td><td>600k - 1M+ 美元</td></tr></tbody></table><p><strong>趋势观察（截至知识截止，需 [实时核对]）：</strong></p><ul><li>2024-2025 AI Infra 是<strong>卖方市场</strong>，头部大模型公司为 infra 人才开出的溢价高于一般后端。</li><li><strong>KV Cache / 推理方向</strong>因直接关系到大模型服务成本，溢价尤其明显。</li><li>大模型创业公司<strong>期权占比大、现金可能低于大厂</strong>，需评估退出预期。</li><li>海外 remote 岗位（NVIDIA/Meta/Together 等）对国内候选人也是重要选项。</li></ul><hr><h2 id="_5-简历匹配建议" tabindex="-1">5. 简历匹配建议 <a class="header-anchor" href="#_5-简历匹配建议" aria-label="Permalink to &quot;5. 简历匹配建议&quot;">​</a></h2><p>把本 Wiki 的知识点映射到简历&quot;能写出来&quot;的经历：</p><ol><li><strong>有推理引擎源码贡献</strong>：给 vLLM/SGLang 提过 PR 是强信号。哪怕一个小优化（KV 调度、prefix caching 边界 case、某算子）。</li><li><strong>做过 KV Cache 相关实验</strong>：复现 PagedAttention/MLA/RadixAttention 的某项指标对比，写成 benchmark 报告。</li><li><strong>有算子优化经历</strong>：写一个 FlashAttention 变体或 FP8 KV 量化 kernel，贴 Nsight profile 数据。</li><li><strong>系统设计能力</strong>：能画出&quot;高并发 LLM serving 系统&quot;架构并讲清调度/KV/分离式。</li><li><strong>论文/开源</strong>：有 OSDI/SOSP/MLSys/ASPLOS/ISCA/SC 任一作，或 vLLM/SGLang/Megatron 显著贡献。</li></ol><blockquote><p>若以上都没有，<strong>本 Wiki 的 2 个月计划</strong>就是用来&quot;制造这些经历&quot;的--第 3-6 周的源码阅读 + 复现 + PR 任务即为此设计。</p></blockquote><hr><h2 id="_6-待你补全的实时信息清单" tabindex="-1">6. 待你补全的实时信息清单 <a class="header-anchor" href="#_6-待你补全的实时信息清单" aria-label="Permalink to &quot;6. 待你补全的实时信息清单&quot;">​</a></h2><p>请用实时渠道补全并回填本页（建议在评论/补充区记录）：</p><ul><li>[ ] 目标公司当前在招的 AI Infra 岗位 JD 原文（3-5 家）</li><li>[ ] 目标公司最新薪资区间与签字费/股票</li><li>[ ] 目标团队的技术栈与近期技术博客/分享</li><li>[ ] 最近 3 个月目标公司的面经原题（牛客/一亩三分地/小红书）</li><li>[ ] 内推联系人（脉脉/校友）</li></ul><p>下一篇：<a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a>。</p>',61)])])}const f=r(i,[["render",o]]);export{u as __pageData,f as default};
